// kit.js -- the shared motion contract for vansh-ishika (ported from suryanshu-rajvi).
// Every motion module imports from here; nothing else is global.
//
// ============================================================================
// THE CONTRACT (read before editing any motion file)
// ============================================================================
// DOM (generated by tools/build.py -- never hand-edit index.html):
//   section.scene[data-scene=<slug>]  > .stage (1080 x H design px; 1 px = var(--u))
//     img.base                          the one composited background plane
//     .ly[data-layer=<id>][data-role]   one PSD layer: <div class="ly"><img></div>
//     .shape[data-layer]                a CSS-drawn PSD vector box
//     .tb[data-text=<scene.block>]      live text block > .tl (one per line) > .r runs
//     a.hit                             a real link over PSD art (none in this design)
//   Layer ids/roles per scene: README.md ("Scene -> layer ids"). Select a layer as
//   layer(scene, "shivling") or [data-scene="monogram"] [data-layer="shivling"].
//
// LIFECYCLE. Nothing animates until the intro dispatches "invite:open" (js/intro.js:
// the temple-gate opening, at the start of its dissolve). Then one IntersectionObserver
// drives every scene:
//   enter(scene)  once, the first time the scene is meaningfully on screen: 30 % of
//                 the scene, 45 % of the viewport, OR ~15 % of the scene's live text
//                 block (a .kit-textzone sentinel over the text's vertical extent) --
//                 so the date / venue start revealing as soon as they scroll in.
//                 Also adds .is-entered to the scene (sticky: text never re-hides).
//   show(scene)   every time it becomes visible   -> start / resume loops
//   hide(scene)   every time it leaves the screen  -> PAUSE loops (iOS budget)
// Register with onScene(slug | [slugs] | "*", { enter, show, hide }).
//
// SCENE MODULES (js/motion/scenes/*.js + css/scenes/*.css, one pair per owner):
//   monogram-names.js (monogram, names) · mehendi-tilak.js (mehendi, tilak)
//   haldi-wedding.js (haldi, wedding) · rsvp.js (rsvp)   -- all EMPTY in phase 1
//   They are imported by js/main.js and linked by build.py already: edit ONLY your
//   own pair. Their init() runs BEFORE the generic modules'.
//   * Claim what you animate: claim(el) (or data-motion="custom" on the element or
//     on the whole section). Generic reveal / ambient / touch skip claimed nodes and
//     everything inside them, and reveal.css does not arm them hidden -- so a
//     claimed element rests on its PSD frame until YOUR code moves it.
//   * Extra overlay DOM (glows, sparkles, light beams, embeds) is created at
//     runtime inside your own scene's .stage, pointer-events:none unless it is
//     interactive, never larger than the stage. Remove/pause it in hide().
//   * Any "armed" (hidden-before-entrance) CSS must be scoped under html.motion so
//     reduced motion / no JS shows the exact PSD frame.
//
// OWNERSHIP of unclaimed nodes (who may write which property):
//   .ly wrapper  transform/opacity -> reveal.js (entrance)
//   .ly wrapper  translate          -> ambient.js (scroll parallax; paper slides only)
//   .ly > img    rotate             -> ambient.js (idle sway)
//   .ly > img    transform          -> touch.js (tap shiver)
//   .tl / .shape transform/opacity/mask -> reveal.js
//   .gate and everything in it      -> intro.js
//   Claimed nodes                   -> the claiming scene module, all properties.
//
// RULES (iOS Safari kills tabs on GPU memory -- repo memory ios-compositor-surface-crashes):
//   transform / opacity only (filter only on small nodes, never animated on
//   stage-sized ones); no will-change on stage-sized nodes; no mix-blend-mode /
//   backdrop-filter on large nodes; no node bigger than the stage; pause loops in
//   hide(); reduced motion = the exact PSD frame (kit.reduced, html.motion absent).
// ============================================================================

export const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
export const root = document.documentElement;
if (!reduced) root.classList.add("motion");

export const ease = {
  out: "cubic-bezier(0.16, 1, 0.3, 1)",      // expo-out: arrivals
  soft: "cubic-bezier(0.22, 0.61, 0.36, 1)",  // gentle settle
  inOut: "cubic-bezier(0.65, 0, 0.35, 1)",    // loops / folds
};

export const wait = (ms) => new Promise((r) => setTimeout(r, ms));

// Design px -> CSS px for a stage (1 design px = stage width / 1080).
export const unit = (stage) => stage.getBoundingClientRect().width / 1080;

export const stageOf = (scene) => scene.querySelector(".stage");
export const sceneEl = (slug) => document.querySelector(`[data-scene="${slug}"]`);
export const layers = (scene, sel = "") => [...scene.querySelectorAll(".ly" + sel)];
export const layer = (scene, id) => scene.querySelector(`.ly[data-layer="${id}"]`);

// ---------------------------------------------------------------- claiming
export function claim(...els) {
  for (const el of els.flat()) if (el) el.dataset.motion = "custom";
}
// true when no scene module has claimed el (or an ancestor of it)
export const free = (el) => !el.closest('[data-motion="custom"]');

// A layer's PSD rect in design px, read once from its inline % style.
export function rectOf(ly) {
  if (ly._rect) return ly._rect;
  const stage = ly.closest(".stage");
  const H = 1080 * (stage.clientHeight / stage.clientWidth || 1920 / 1080);
  const pc = (k) => parseFloat(ly.style[k]) / 100 || 0;
  const r = { x: pc("left") * 1080, y: pc("top") * H, w: pc("width") * 1080, h: pc("height") * H, H };
  const e = 2;
  Object.assign(r, { top: r.y <= e, bottom: r.y + r.h >= H - e, left: r.x <= e, right: r.x + r.w >= 1080 - e });
  r.full = r.w >= 1080 * 0.9 && r.h >= H * 0.9;
  return (ly._rect = r);
}

// Where a layer's "stem" is: the stage edge(s) the art is cut by (border florals
// grow from the edge they hang off), else its foot (grounded plants).
export function stemOrigin(ly) {
  const r = rectOf(ly);
  const h = r.left && !r.right ? "0%" : r.right && !r.left ? "100%" : "50%";
  const v = r.top && !r.bottom ? "0%" : "100%";
  if (h !== "50%" && !r.top && !r.bottom) return `${h} 50%`;   // cut by a side only
  return `${h} ${v}`;
}

// ---------------------------------------------------------------- text zone
// The live text's ink box in design px [x0, y0, x1, y1] (union of every .tb run; script
// runs widen by a quarter of their height for swashes that overhang their advance).
// Measured lazily -- fonts settle late -- and cached per stage width once fonts load.
const SCRIPT_RUN = /Maginia|Hello Bride/i;
export function textZone(stage) {
  const r = stage.getBoundingClientRect();
  const u = r.width / 1080;
  if (!u) return null;
  if (stage._tz && stage._tz.w === r.width) return stage._tz.box;
  let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;
  for (const run of stage.querySelectorAll(".tb .r")) {
    const b = run.getBoundingClientRect();
    if (!b.width || !b.height) continue;
    const sw = SCRIPT_RUN.test(run.style.fontFamily) ? b.height * 0.25 : 0;
    x0 = Math.min(x0, b.left - sw); y0 = Math.min(y0, b.top);
    x1 = Math.max(x1, b.right + sw); y1 = Math.max(y1, b.bottom);
  }
  const box = x1 < x0 ? null : [(x0 - r.left) / u, (y0 - r.top) / u, (x1 - r.left) / u, (y1 - r.top) / u];
  if (!document.fonts || document.fonts.status === "loaded") stage._tz = { w: r.width, box };
  return box;
}

// Ambient sprites (drifting petals, bracts) keep off the text: a candidate path
// { pos(k) -> [x, y] sprite centre in design px for k 0..1, r radius in design px }
// "runs" until it would touch the text zone padded by `pad` (1 = never touches).
export function clearRun(stage, path, pad = 20, steps = 64) {
  const z = textZone(stage);
  if (!z) return 1;
  const m = pad + path.r;
  const [x0, y0, x1, y1] = [z[0] - m, z[1] - m, z[2] + m, z[3] + m];
  for (let i = 0; i <= steps; i++) {
    const [x, y] = path.pos(i / steps);
    if (x > x0 && x < x1 && y > y0 && y < y1) return Math.max(0, (i - 1) / steps);
  }
  return 1;
}
// Try up to `tries` candidates from make(); return the first that never meets the text
// (run = 1), else the one that runs longest, if it runs at least `min` -- the caller then
// plays only that part (path.run) and fades the sprite out by its end. null = skip it.
export function routeClear(stage, make, { tries = 8, min = 0.25, pad = 20 } = {}) {
  let best = null;
  for (let i = 0; i < tries; i++) {
    const p = make(i);
    if (!p) continue;
    p.run = clearRun(stage, p, pad);
    if (p.run >= 1) return p;
    if (!best || p.run > best.run) best = p;
  }
  return best && best.run >= min ? best : null;
}

// ---------------------------------------------------------------- tap actions
// A scene module registers what its slide does on a tap (no finger point needed) so the
// slide's "Tap to ..." pill (js/motion/hints.js, a real <button>) can trigger the same
// effect from a click or the keyboard. hints.js only builds a pill for registered slugs.
const tapActions = new Map();
export function tapAction(slug, fn) { tapActions.set(slug, fn); }
export const tapActionOf = (slug) => tapActions.get(slug);

// ---------------------------------------------------------------- lifecycle
let opened = false;
const openQueue = [];
export function onOpen(fn) { opened ? fn() : openQueue.push(fn); }
document.addEventListener("invite:open", () => {
  if (opened) return;
  opened = true;
  openQueue.splice(0).forEach((f) => f());
});

const handlers = [];
export function onScene(slug, h) { handlers.push({ slugs: [].concat(slug), ...h }); }
function fire(kind, scene) {
  for (const h of handlers) {
    if ((h.slugs.includes("*") || h.slugs.includes(scene.dataset.scene)) && h[kind]) {
      try { h[kind](scene); } catch (e) { console.error(`[motion] ${kind} ${scene.dataset.scene}`, e); }
    }
  }
}

// Fail-safe: put every scene in its entered (resting) state. Called on any
// setup error and on pagehide (print / bfcache), so content is never stuck hidden.
export function enterAll() {
  document.querySelectorAll("[data-scene]").forEach((s) => s.classList.add("is-entered"));
}

export function start() {
  window.addEventListener("pagehide", enterAll);
  if (typeof window.IntersectionObserver !== "function") { enterAll(); return; }
  if (!document.querySelector("[data-intro]")) { opened = true; openQueue.splice(0).forEach((f) => f()); }
  onOpen(() => {
    const visible = new Set();
    const enter = (s) => {
      if (s.classList.contains("is-entered")) return;
      s.classList.add("is-entered");
      fire("enter", s);
    };
    // The text's own trigger: ~15 % of its block on screen enters the scene, even
    // when the scene as a whole is not yet 30 % in (the guest came to read it).
    const tio = new IntersectionObserver((entries) => {
      for (const e of entries) {
        if (e.isIntersecting && e.intersectionRatio >= 0.15) {
          enter(e.target.closest("[data-scene]"));
          tio.unobserve(e.target);
        }
      }
    }, { threshold: [0, 0.15, 0.3] });
    document.querySelectorAll("[data-scene]").forEach((s) => {
      const stage = stageOf(s);
      const z = stage && textZone(stage);
      if (!z) return;
      const H = 1080 * (stage.clientHeight / stage.clientWidth || 1920 / 1080);
      const zone = document.createElement("div");
      zone.className = "kit-textzone";
      zone.setAttribute("aria-hidden", "true");
      Object.assign(zone.style, {
        position: "absolute", left: "0", width: "100%", pointerEvents: "none", visibility: "hidden",
        top: `${(Math.max(0, z[1]) / H) * 100}%`, height: `${((Math.min(H, z[3]) - Math.max(0, z[1])) / H) * 100}%`,
      });
      stage.appendChild(zone);
      tio.observe(zone);
    });
    const io = new IntersectionObserver((entries) => {
      for (const e of entries) {
        const s = e.target;
        // "Entered" = 30% of the scene, or 45% of the viewport (or the text, above).
        const big = e.intersectionRect.height >= window.innerHeight * 0.45;
        if (e.intersectionRatio >= 0.3 || big) enter(s);
        // Edge contact counts as "intersecting" in Chrome; require real overlap.
        const on = e.isIntersecting && e.intersectionRect.height > 2;
        if (on && !visible.has(s)) { visible.add(s); fire("show", s); }
        else if (!on && visible.has(s)) { visible.delete(s); fire("hide", s); }
      }
    }, { threshold: [0, 0.01, 0.1, 0.2, 0.3, 0.45, 0.6] });
    document.querySelectorAll("[data-scene]").forEach((s) => io.observe(s));
  });
}
